contracts/PaywallCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title PaywallCore
 * @notice Main payment contract for paywall access control
 * @dev Handles USDC payments, device verification, and access grants
 */
contract PaywallCore is ReentrancyGuard, AccessControl, Pausable {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");

    IERC20 public immutable usdcToken;
    address public treasury;
    uint256 public platformFeeBps = 250; // 2.5% in basis points
    uint256 public constant MAX_FEE_BPS = 750; // 7.5% max platform fee

    uint256 private nextContentId = 1;
    uint256 private nextPaymentId = 1;

    struct Content {
        uint256 contentId;
        address creator;
        uint256 priceUSDC;           // Price in USDC (6 decimals)
        uint256 accessDuration;       // Duration in seconds (0 = lifetime)
        uint256 maxDevices;           // Max concurrent devices
        bool isActive;
        uint256 totalRevenue;
        uint256 accessCount;
        string contentHash;           // IPFS hash or content identifier
        uint256 createdAt;
    }

    struct Payment {
        bytes32 paymentHash;          // SHA256 hash of preimage (x402 style)
        address payer;
        uint256 contentId;
        uint256 amount;
        uint256 timestamp;
        uint256 expiresAt;
        bool completed;
        bool refunded;
        bytes32[] deviceFingerprints; // Devices that accessed via this payment
    }

    struct DeviceAccess {
        bytes32 deviceFingerprint;    // keccak256(fingerprint data)
        address payer;
        uint256 contentId;
        uint256 grantedAt;
        uint256 expiresAt;
        uint256 accessCount;
        bool isRevoked;
    }

    // Mappings
    mapping(uint256 => Content) public contents;
    mapping(bytes32 => Payment) public payments;
    mapping(bytes32 => DeviceAccess) public deviceAccess; // keccak256(contentId, deviceFingerprint)
    mapping(address => uint256) public creatorBalances;
    mapping(uint256 => mapping(bytes32 => bool)) public contentDeviceUsed;
    mapping(address => uint256[]) public creatorContent;
    mapping(uint256 => uint256) public contentDeviceCount;

    // Events
    event ContentRegistered(
        uint256 indexed contentId, 
        address indexed creator, 
        uint256 price, 
        string contentHash
    );

    event PaymentCreated(
        bytes32 indexed paymentHash, 
        address indexed payer, 
        uint256 indexed contentId, 
        uint256 amount,
        uint256 expiresAt
    );

    event PaymentCompleted(
        bytes32 indexed paymentHash, 
        bytes32 deviceFingerprint, 
        uint256 creatorAmount, 
        uint256 platformFee
    );

    event AccessGranted(
        uint256 indexed contentId, 
        bytes32 indexed deviceFingerprint, 
        address indexed payer,
        uint256 expiresAt
    );

    event DeviceRevoked(
        uint256 indexed contentId, 
        bytes32 indexed deviceFingerprint,
        address revokedBy
    );

    event CreatorWithdrawal(address indexed creator, uint256 amount);

    event ContentStatusChanged(uint256 indexed contentId, bool isActive);

    constructor(address _usdcToken, address _treasury) {
        require(_usdcToken != address(0), "Invalid USDC token address");
        require(_treasury != address(0), "Invalid treasury address");

        usdcToken = IERC20(_usdcToken);
        treasury = _treasury;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    /**
     * @notice Register new content for monetization
     */
    function registerContent(
        uint256 priceUSDC,
        uint256 accessDuration,
        uint256 maxDevices,
        string calldata contentHash
    ) external whenNotPaused returns (uint256 contentId) {
        require(priceUSDC > 0, "Price must be greater than 0");
        require(maxDevices > 0, "Max devices must be greater than 0");
        require(bytes(contentHash).length > 0, "Content hash required");

        contentId = nextContentId++;

        contents[contentId] = Content({
            contentId: contentId,
            creator: msg.sender,
            priceUSDC: priceUSDC,
            accessDuration: accessDuration,
            maxDevices: maxDevices,
            isActive: true,
            totalRevenue: 0,
            accessCount: 0,
            contentHash: contentHash,
            createdAt: block.timestamp
        });

        creatorContent[msg.sender].push(contentId);

        emit ContentRegistered(contentId, msg.sender, priceUSDC, contentHash);
    }

    /**
     * @notice Create a payment intent with hash commitment
     */
    function createPayment(
        bytes32 paymentHash,
        uint256 contentId,
        uint256 expiryMinutes
    ) external payable whenNotPaused returns (bytes32 paymentId) {
        require(contents[contentId].isActive, "Content not active");
        require(expiryMinutes > 0 && expiryMinutes <= 1440, "Invalid expiry"); // Max 24 hours

        Content storage content = contents[contentId];
        uint256 expiresAt = block.timestamp + (expiryMinutes * 60);

        paymentId = keccak256(abi.encodePacked(paymentHash, block.timestamp, nextPaymentId++));

        payments[paymentId] = Payment({
            paymentHash: paymentHash,
            payer: msg.sender,
            contentId: contentId,
            amount: content.priceUSDC,
            timestamp: block.timestamp,
            expiresAt: expiresAt,
            completed: false,
            refunded: false,
            deviceFingerprints: new bytes32[](0)
        });

        // Transfer USDC from payer (held in escrow until completion)
        require(
            usdcToken.transferFrom(msg.sender, address(this), content.priceUSDC),
            "USDC transfer failed"
        );

        emit PaymentCreated(paymentHash, msg.sender, contentId, content.priceUSDC, expiresAt);

        return paymentId;
    }

    /**
     * @notice Complete payment by revealing preimage and registering device
     */
    function completePayment(
        bytes32 preimage,
        bytes32 deviceFingerprint
    ) external nonReentrant whenNotPaused returns (bool) {
        bytes32 paymentHash = sha256(abi.encodePacked(preimage));
        bytes32 paymentId = findPaymentByHash(paymentHash);

        require(paymentId != bytes32(0), "Payment not found");

        Payment storage payment = payments[paymentId];
        require(!payment.completed, "Payment already completed");
        require(!payment.refunded, "Payment already refunded");
        require(block.timestamp <= payment.expiresAt, "Payment expired");
        require(payment.payer == msg.sender, "Not payment creator");

        Content storage content = contents[payment.contentId];
        require(content.isActive, "Content not active");

        // Check device limits
        require(
            contentDeviceCount[payment.contentId] < content.maxDevices ||
            contentDeviceUsed[payment.contentId][deviceFingerprint],
            "Device limit exceeded"
        );

        // Mark payment as completed
        payment.completed = true;
        payment.deviceFingerprints.push(deviceFingerprint);

        // Grant device access
        bytes32 accessKey = keccak256(abi.encodePacked(payment.contentId, deviceFingerprint));
        uint256 accessExpiresAt = content.accessDuration == 0 
            ? type(uint256).max 
            : block.timestamp + content.accessDuration;

        deviceAccess[accessKey] = DeviceAccess({
            deviceFingerprint: deviceFingerprint,
            payer: msg.sender,
            contentId: payment.contentId,
            grantedAt: block.timestamp,
            expiresAt: accessExpiresAt,
            accessCount: 0,
            isRevoked: false
        });

        // Update device tracking
        if (!contentDeviceUsed[payment.contentId][deviceFingerprint]) {
            contentDeviceUsed[payment.contentId][deviceFingerprint] = true;
            contentDeviceCount[payment.contentId]++;
        }

        // Calculate fees and distribute payment
        uint256 platformFee = (payment.amount * platformFeeBps) / 10000;
        uint256 creatorAmount = payment.amount - platformFee;

        creatorBalances[content.creator] += creatorAmount;

        // Transfer platform fee to treasury
        require(usdcToken.transfer(treasury, platformFee), "Treasury transfer failed");

        // Update content stats
        content.totalRevenue += payment.amount;
        content.accessCount++;

        emit PaymentCompleted(paymentHash, deviceFingerprint, creatorAmount, platformFee);
        emit AccessGranted(payment.contentId, deviceFingerprint, msg.sender, accessExpiresAt);

        return true;
    }

    /**
     * @notice Verify if device has access to content
     */
    function verifyAccess(
        uint256 contentId,
        bytes32 deviceFingerprint,
        address user
    ) external view returns (bool hasAccess, uint256 expiresAt) {
        bytes32 accessKey = keccak256(abi.encodePacked(contentId, deviceFingerprint));
        DeviceAccess storage access = deviceAccess[accessKey];

        if (access.payer == address(0) || 
            access.isRevoked || 
            access.payer != user ||
            block.timestamp > access.expiresAt) {
            return (false, 0);
        }

        return (true, access.expiresAt);
    }

    /**
     * @notice Increment access count for analytics
     */
    function recordAccess(
        uint256 contentId,
        bytes32 deviceFingerprint
    ) external {
        bytes32 accessKey = keccak256(abi.encodePacked(contentId, deviceFingerprint));
        require(deviceAccess[accessKey].payer != address(0), "No access found");

        deviceAccess[accessKey].accessCount++;
    }

    /**
     * @notice Refund expired payment
     */
    function refundExpiredPayment(bytes32 paymentHash) external nonReentrant {
        bytes32 paymentId = findPaymentByHash(paymentHash);
        require(paymentId != bytes32(0), "Payment not found");

        Payment storage payment = payments[paymentId];
        require(!payment.completed, "Payment already completed");
        require(!payment.refunded, "Payment already refunded");
        require(block.timestamp > payment.expiresAt, "Payment not expired");

        payment.refunded = true;

        require(usdcToken.transfer(payment.payer, payment.amount), "Refund failed");
    }

    /**
     * @notice Creator withdraws earned balance
     */
    function withdrawCreatorBalance() external nonReentrant {
        uint256 balance = creatorBalances[msg.sender];
        require(balance > 0, "No balance to withdraw");

        creatorBalances[msg.sender] = 0;

        require(usdcToken.transfer(msg.sender, balance), "Withdrawal failed");

        emit CreatorWithdrawal(msg.sender, balance);
    }

    /**
     * @notice Update content price (creator only)
     */
    function updateContentPrice(uint256 contentId, uint256 newPrice) external {
        require(contents[contentId].creator == msg.sender, "Not content creator");
        require(newPrice > 0, "Price must be greater than 0");

        contents[contentId].priceUSDC = newPrice;
    }

    /**
     * @notice Revoke device access (creator or admin)
     */
    function revokeDeviceAccess(
        uint256 contentId, 
        bytes32 deviceFingerprint
    ) external {
        require(
            contents[contentId].creator == msg.sender || 
            hasRole(ADMIN_ROLE, msg.sender),
            "Unauthorized"
        );

        bytes32 accessKey = keccak256(abi.encodePacked(contentId, deviceFingerprint));
        require(deviceAccess[accessKey].payer != address(0), "Access not found");

        deviceAccess[accessKey].isRevoked = true;

        emit DeviceRevoked(contentId, deviceFingerprint, msg.sender);
    }

    // Admin functions

    /**
     * @notice Set platform fee (admin only)
     */
    function setPlatformFee(uint256 feeBps) external onlyRole(ADMIN_ROLE) {
        require(feeBps <= MAX_FEE_BPS, "Fee too high");
        platformFeeBps = feeBps;
    }

    /**
     * @notice Pause/unpause content (admin only)
     */
    function setContentStatus(uint256 contentId, bool isActive) external onlyRole(ADMIN_ROLE) {
        require(contents[contentId].creator != address(0), "Content not found");
        contents[contentId].isActive = isActive;

        emit ContentStatusChanged(contentId, isActive);
    }

    /**
     * @notice Emergency pause (admin only)
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @notice Unpause (admin only)
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    /**
     * @notice Update treasury address (admin only)
     */
    function updateTreasury(address newTreasury) external onlyRole(ADMIN_ROLE) {
        require(newTreasury != address(0), "Invalid treasury address");
        treasury = newTreasury;
    }

    // View functions

    /**
     * @notice Get creator's content IDs
     */
    function getCreatorContent(address creator) external view returns (uint256[] memory) {
        return creatorContent[creator];
    }

    /**
     * @notice Get content details
     */
    function getContent(uint256 contentId) external view returns (Content memory) {
        return contents[contentId];
    }

    /**
     * @notice Get payment details
     */
    function getPayment(bytes32 paymentId) external view returns (Payment memory) {
        return payments[paymentId];
    }

    /**
     * @notice Find payment by hash (internal helper)
     */
    function findPaymentByHash(bytes32 paymentHash) internal view returns (bytes32) {
        // In practice, this would need a more efficient lookup mechanism
        // For now, simplified implementation
        for (uint256 i = 1; i < nextPaymentId; i++) {
            bytes32 testId = keccak256(abi.encodePacked(paymentHash, i));
            if (payments[testId].paymentHash == paymentHash) {
                return testId;
            }
        }
        return bytes32(0);
    }
}

contracts/PaywallRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title PaywallRegistry
 * @notice Central registry for creators, content, and platform configuration
 */
contract PaywallRegistry is AccessControl, Pausable {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");

    enum ContentType { VIDEO, DOCUMENT, LIVESTREAM, API, SOFTWARE, OTHER }

    struct Creator {
        address wallet;
        bool isVerified;
        bool isActive;
        uint256 totalRevenue;
        uint256 totalContent;
        uint256 totalSubscribers;
        uint256 registeredAt;
        string profileHash;          // IPFS hash of profile metadata
        string name;
        string email;
        uint256 customFeeBps;        // Custom fee rate (0 = use default)
    }

    struct ContentMetadata {
        uint256 contentId;
        address creator;
        ContentType contentType;
        string title;
        string description;
        string thumbnailHash;        // IPFS hash of thumbnail
        string[] tags;
        uint256 createdAt;
        uint256 lastModified;
        bool isFeatured;
        uint256 rating;              // Average rating (1-5 stars * 100)
        uint256 ratingCount;
    }

    struct PlatformConfig {
        uint256 defaultFeeBps;       // Default platform fee
        uint256 maxFeeBps;           // Maximum allowed fee
        address treasury;
        address feeRecipient;
        bool paymentsEnabled;
        bool subscriptionsEnabled;
        uint256 minContentPrice;     // Minimum content price in USDC
        uint256 maxContentPrice;     // Maximum content price in USDC
    }

    struct CategoryConfig {
        ContentType category;
        uint256 feeBps;              // Category-specific fee
        bool isActive;
        string name;
        uint256 minPrice;
        uint256 maxPrice;
    }

    // State variables
    PlatformConfig public platformConfig;

    // Mappings
    mapping(address => Creator) public creators;
    mapping(uint256 => ContentMetadata) public contentMetadata;
    mapping(ContentType => CategoryConfig) public categoryConfigs;
    mapping(address => bool) public bannedCreators;
    mapping(uint256 => bool) public featuredContent;
    mapping(address => uint256[]) public creatorContentIds;
    mapping(bytes32 => bool) public usedProfileHashes; // Prevent duplicate profiles

    // Statistics
    uint256 public totalCreators;
    uint256 public totalVerifiedCreators;
    uint256 public totalContent;
    uint256 public totalRevenue;

    // Events
    event CreatorRegistered(
        address indexed creator, 
        string name, 
        string profileHash, 
        uint256 timestamp
    );

    event CreatorVerified(address indexed creator, address verifiedBy);

    event CreatorStatusChanged(address indexed creator, bool isActive);

    event ContentRegistered(
        uint256 indexed contentId,
        address indexed creator,
        ContentType contentType,
        string title
    );

    event ContentMetadataUpdated(
        uint256 indexed contentId,
        string title,
        string description
    );

    event ContentFeatured(uint256 indexed contentId, bool featured);

    event ContentRated(
        uint256 indexed contentId,
        address rater,
        uint256 rating,
        uint256 newAverage
    );

    event PlatformConfigUpdated(
        uint256 defaultFeeBps,
        address treasury,
        bool paymentsEnabled
    );

    event CategoryConfigUpdated(
        ContentType indexed category,
        uint256 feeBps,
        bool isActive
    );

    constructor(address _treasury) {
        require(_treasury != address(0), "Invalid treasury address");

        platformConfig = PlatformConfig({
            defaultFeeBps: 250,          // 2.5%
            maxFeeBps: 750,              // 7.5%
            treasury: _treasury,
            feeRecipient: _treasury,
            paymentsEnabled: true,
            subscriptionsEnabled: true,
            minContentPrice: 1e6,        // 1 USDC
            maxContentPrice: 10000e6     // 10,000 USDC
        });

        // Initialize default category configurations
        _initializeCategories();

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(VERIFIER_ROLE, msg.sender);
    }

    /**
     * @notice Register as a content creator
     */
    function registerCreator(
        string calldata name,
        string calldata email,
        string calldata profileHash
    ) external whenNotPaused {
        require(creators[msg.sender].registeredAt == 0, "Creator already registered");
        require(bytes(name).length > 0, "Name required");
        require(bytes(profileHash).length > 0, "Profile hash required");
        require(!usedProfileHashes[keccak256(bytes(profileHash))], "Profile hash already used");

        creators[msg.sender] = Creator({
            wallet: msg.sender,
            isVerified: false,
            isActive: true,
            totalRevenue: 0,
            totalContent: 0,
            totalSubscribers: 0,
            registeredAt: block.timestamp,
            profileHash: profileHash,
            name: name,
            email: email,
            customFeeBps: 0
        });

        usedProfileHashes[keccak256(bytes(profileHash))] = true;
        totalCreators++;

        emit CreatorRegistered(msg.sender, name, profileHash, block.timestamp);
    }

    /**
     * @notice Verify a creator (verifier only)
     */
    function verifyCreator(address creator) external onlyRole(VERIFIER_ROLE) {
        require(creators[creator].registeredAt > 0, "Creator not registered");
        require(!creators[creator].isVerified, "Creator already verified");

        creators[creator].isVerified = true;
        totalVerifiedCreators++;

        emit CreatorVerified(creator, msg.sender);
    }

    /**
     * @notice Update creator profile
     */
    function updateCreatorProfile(
        string calldata name,
        string calldata email,
        string calldata newProfileHash
    ) external {
        require(creators[msg.sender].registeredAt > 0, "Creator not registered");

        Creator storage creator = creators[msg.sender];

        if (bytes(newProfileHash).length > 0 && 
            keccak256(bytes(newProfileHash)) != keccak256(bytes(creator.profileHash))) {
            require(!usedProfileHashes[keccak256(bytes(newProfileHash))], "Profile hash already used");

            // Remove old hash and add new one
            usedProfileHashes[keccak256(bytes(creator.profileHash))] = false;
            usedProfileHashes[keccak256(bytes(newProfileHash))] = true;

            creator.profileHash = newProfileHash;
        }

        if (bytes(name).length > 0) {
            creator.name = name;
        }

        if (bytes(email).length > 0) {
            creator.email = email;
        }
    }

    /**
     * @notice Register content metadata
     */
    function registerContentMetadata(
        uint256 contentId,
        address creator,
        ContentType contentType,
        string calldata title,
        string calldata description,
        string calldata thumbnailHash,
        string[] calldata tags
    ) external onlyRole(ADMIN_ROLE) {
        require(creators[creator].registeredAt > 0, "Creator not registered");
        require(contentMetadata[contentId].contentId == 0, "Content already registered");
        require(bytes(title).length > 0, "Title required");

        contentMetadata[contentId] = ContentMetadata({
            contentId: contentId,
            creator: creator,
            contentType: contentType,
            title: title,
            description: description,
            thumbnailHash: thumbnailHash,
            tags: tags,
            createdAt: block.timestamp,
            lastModified: block.timestamp,
            isFeatured: false,
            rating: 0,
            ratingCount: 0
        });

        creatorContentIds[creator].push(contentId);
        creators[creator].totalContent++;
        totalContent++;

        emit ContentRegistered(contentId, creator, contentType, title);
    }

    /**
     * @notice Update content metadata
     */
    function updateContentMetadata(
        uint256 contentId,
        string calldata title,
        string calldata description,
        string calldata thumbnailHash,
        string[] calldata tags
    ) external {
        ContentMetadata storage content = contentMetadata[contentId];
        require(content.contentId != 0, "Content not found");
        require(
            content.creator == msg.sender || hasRole(ADMIN_ROLE, msg.sender),
            "Unauthorized"
        );

        if (bytes(title).length > 0) {
            content.title = title;
        }

        if (bytes(description).length > 0) {
            content.description = description;
        }

        if (bytes(thumbnailHash).length > 0) {
            content.thumbnailHash = thumbnailHash;
        }

        if (tags.length > 0) {
            content.tags = tags;
        }

        content.lastModified = block.timestamp;

        emit ContentMetadataUpdated(contentId, title, description);
    }

    /**
     * @notice Rate content (1-5 stars)
     */
    function rateContent(uint256 contentId, uint256 rating) external {
        require(contentMetadata[contentId].contentId != 0, "Content not found");
        require(rating >= 100 && rating <= 500, "Rating must be 1-5 stars (100-500)");

        ContentMetadata storage content = contentMetadata[contentId];

        // Calculate new average rating
        uint256 totalRating = content.rating * content.ratingCount + rating;
        content.ratingCount++;
        content.rating = totalRating / content.ratingCount;

        emit ContentRated(contentId, msg.sender, rating, content.rating);
    }

    /**
     * @notice Feature/unfeature content (admin only)
     */
    function setContentFeatured(uint256 contentId, bool featured) external onlyRole(ADMIN_ROLE) {
        require(contentMetadata[contentId].contentId != 0, "Content not found");

        contentMetadata[contentId].isFeatured = featured;
        featuredContent[contentId] = featured;

        emit ContentFeatured(contentId, featured);
    }

    /**
     * @notice Update creator statistics (called by main contracts)
     */
    function updateCreatorStats(
        address creator,
        uint256 revenueIncrease,
        uint256 subscriberChange,
        bool isSubscriberIncrease
    ) external onlyRole(ADMIN_ROLE) {
        require(creators[creator].registeredAt > 0, "Creator not registered");

        Creator storage creatorData = creators[creator];
        creatorData.totalRevenue += revenueIncrease;

        if (isSubscriberIncrease) {
            creatorData.totalSubscribers += subscriberChange;
        } else {
            creatorData.totalSubscribers = creatorData.totalSubscribers > subscriberChange 
                ? creatorData.totalSubscribers - subscriberChange 
                : 0;
        }

        totalRevenue += revenueIncrease;
    }

    /**
     * @notice Set custom fee rate for creator (admin only)
     */
    function setCreatorCustomFee(address creator, uint256 feeBps) external onlyRole(ADMIN_ROLE) {
        require(creators[creator].registeredAt > 0, "Creator not registered");
        require(feeBps <= platformConfig.maxFeeBps, "Fee too high");

        creators[creator].customFeeBps = feeBps;
    }

    /**
     * @notice Ban/unban creator (admin only)
     */
    function setCreatorStatus(address creator, bool isActive) external onlyRole(ADMIN_ROLE) {
        require(creators[creator].registeredAt > 0, "Creator not registered");

        creators[creator].isActive = isActive;
        bannedCreators[creator] = !isActive;

        emit CreatorStatusChanged(creator, isActive);
    }

    // Platform configuration functions (admin only)

    /**
     * @notice Update platform configuration
     */
    function updatePlatformConfig(
        uint256 defaultFeeBps,
        uint256 maxFeeBps,
        address treasury,
        bool paymentsEnabled,
        bool subscriptionsEnabled,
        uint256 minContentPrice,
        uint256 maxContentPrice
    ) external onlyRole(ADMIN_ROLE) {
        require(treasury != address(0), "Invalid treasury address");
        require(defaultFeeBps <= maxFeeBps, "Default fee cannot exceed max");
        require(maxContentPrice >= minContentPrice, "Invalid price range");

        platformConfig.defaultFeeBps = defaultFeeBps;
        platformConfig.maxFeeBps = maxFeeBps;
        platformConfig.treasury = treasury;
        platformConfig.paymentsEnabled = paymentsEnabled;
        platformConfig.subscriptionsEnabled = subscriptionsEnabled;
        platformConfig.minContentPrice = minContentPrice;
        platformConfig.maxContentPrice = maxContentPrice;

        emit PlatformConfigUpdated(defaultFeeBps, treasury, paymentsEnabled);
    }

    /**
     * @notice Update category configuration
     */
    function updateCategoryConfig(
        ContentType category,
        uint256 feeBps,
        bool isActive,
        string calldata name,
        uint256 minPrice,
        uint256 maxPrice
    ) external onlyRole(ADMIN_ROLE) {
        require(feeBps <= platformConfig.maxFeeBps, "Fee too high");
        require(maxPrice >= minPrice, "Invalid price range");

        categoryConfigs[category] = CategoryConfig({
            category: category,
            feeBps: feeBps,
            isActive: isActive,
            name: name,
            minPrice: minPrice,
            maxPrice: maxPrice
        });

        emit CategoryConfigUpdated(category, feeBps, isActive);
    }

    // View functions

    /**
     * @notice Get creator details
     */
    function getCreator(address creator) external view returns (Creator memory) {
        return creators[creator];
    }

    /**
     * @notice Get content metadata
     */
    function getContentMetadata(uint256 contentId) external view returns (ContentMetadata memory) {
        return contentMetadata[contentId];
    }

    /**
     * @notice Get creator's content IDs
     */
    function getCreatorContentIds(address creator) external view returns (uint256[] memory) {
        return creatorContentIds[creator];
    }

    /**
     * @notice Get effective fee rate for creator/content
     */
    function getEffectiveFeeRate(address creator, ContentType contentType) 
        external 
        view 
        returns (uint256) 
    {
        // Check custom creator fee
        if (creators[creator].customFeeBps > 0) {
            return creators[creator].customFeeBps;
        }

        // Check category-specific fee
        if (categoryConfigs[contentType].isActive && categoryConfigs[contentType].feeBps > 0) {
            return categoryConfigs[contentType].feeBps;
        }

        // Return default platform fee
        return platformConfig.defaultFeeBps;
    }

    /**
     * @notice Check if creator is active and not banned
     */
    function isCreatorActive(address creator) external view returns (bool) {
        return creators[creator].isActive && !bannedCreators[creator];
    }

    /**
     * @notice Get platform statistics
     */
    function getPlatformStats() external view returns (
        uint256 _totalCreators,
        uint256 _totalVerifiedCreators,
        uint256 _totalContent,
        uint256 _totalRevenue
    ) {
        return (totalCreators, totalVerifiedCreators, totalContent, totalRevenue);
    }

    // Internal functions

    /**
     * @notice Initialize default category configurations
     */
    function _initializeCategories() internal {
        categoryConfigs[ContentType.VIDEO] = CategoryConfig({
            category: ContentType.VIDEO,
            feeBps: 250,
            isActive: true,
            name: "Video Content",
            minPrice: 1e6,      // 1 USDC
            maxPrice: 1000e6    // 1,000 USDC
        });

        categoryConfigs[ContentType.DOCUMENT] = CategoryConfig({
            category: ContentType.DOCUMENT,
            feeBps: 200,
            isActive: true,
            name: "Documents",
            minPrice: 1e6,      // 1 USDC
            maxPrice: 100e6     // 100 USDC
        });

        categoryConfigs[ContentType.LIVESTREAM] = CategoryConfig({
            category: ContentType.LIVESTREAM,
            feeBps: 300,
            isActive: true,
            name: "Live Streaming",
            minPrice: 5e6,      // 5 USDC
            maxPrice: 500e6     // 500 USDC
        });

        categoryConfigs[ContentType.API] = CategoryConfig({
            category: ContentType.API,
            feeBps: 150,
            isActive: true,
            name: "API Access",
            minPrice: 1e6,      // 1 USDC
            maxPrice: 10000e6   // 10,000 USDC
        });

        categoryConfigs[ContentType.SOFTWARE] = CategoryConfig({
            category: ContentType.SOFTWARE,
            feeBps: 200,
            isActive: true,
            name: "Software",
            minPrice: 10e6,     // 10 USDC
            maxPrice: 5000e6    // 5,000 USDC
        });

        categoryConfigs[ContentType.OTHER] = CategoryConfig({
            category: ContentType.OTHER,
            feeBps: 250,
            isActive: true,
            name: "Other Content",
            minPrice: 1e6,      // 1 USDC
            maxPrice: 1000e6    // 1,000 USDC
        });
    }

    /**
     * @notice Emergency pause (admin only)
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @notice Unpause (admin only)
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

contracts/PaywallSubscriptions.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title PaywallSubscriptions
 * @notice Handles recurring subscription payments for content access
 */
contract PaywallSubscriptions is ReentrancyGuard, AccessControl, Pausable {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    IERC20 public immutable usdcToken;
    address public treasury;
    uint256 public platformFeeBps = 250; // 2.5% in basis points

    uint256 private nextPlanId = 1;
    uint256 private nextSubscriptionId = 1;

    uint256 public constant GRACE_PERIOD = 3 days;
    uint256 public constant MONTH_DURATION = 30 days;
    uint256 public constant YEAR_DURATION = 365 days;

    struct SubscriptionPlan {
        uint256 planId;
        address creator;
        string name;
        string description;
        uint256 monthlyPriceUSDC;
        uint256 annualPriceUSDC;     // Typically discounted
        uint256 maxDevices;
        uint256[] includedContentIds;
        bool isActive;
        uint256 subscriberCount;
        uint256 createdAt;
    }

    struct Subscription {
        uint256 subscriptionId;
        address subscriber;
        uint256 planId;
        uint256 startedAt;
        uint256 currentPeriodStart;
        uint256 currentPeriodEnd;
        uint256 nextBillingDate;
        bool isAnnual;
        bool autoRenew;
        bool isCancelled;
        bytes32[] registeredDevices;
        uint256 totalPaid;
    }

    struct SubscriptionAccess {
        uint256 subscriptionId;
        bytes32 deviceFingerprint;
        uint256 grantedAt;
        uint256 accessCount;
        bool isActive;
    }

    // Mappings
    mapping(uint256 => SubscriptionPlan) public plans;
    mapping(uint256 => Subscription) public subscriptions;
    mapping(address => uint256[]) public userSubscriptions;
    mapping(address => uint256[]) public creatorPlans;
    mapping(bytes32 => SubscriptionAccess) public subscriptionAccess; // keccak256(subscriptionId, deviceFingerprint)
    mapping(address => uint256) public creatorBalances;
    mapping(uint256 => mapping(uint256 => bool)) public planContentIncluded;

    // Events
    event PlanCreated(
        uint256 indexed planId,
        address indexed creator,
        string name,
        uint256 monthlyPrice,
        uint256 annualPrice
    );

    event Subscribed(
        uint256 indexed subscriptionId,
        address indexed subscriber,
        uint256 indexed planId,
        bool isAnnual,
        uint256 amount
    );

    event SubscriptionRenewed(
        uint256 indexed subscriptionId,
        uint256 amount,
        uint256 newPeriodEnd
    );

    event SubscriptionCancelled(
        uint256 indexed subscriptionId,
        address indexed subscriber
    );

    event DeviceRegistered(
        uint256 indexed subscriptionId,
        bytes32 deviceFingerprint
    );

    event CreatorWithdrawal(address indexed creator, uint256 amount);

    constructor(address _usdcToken, address _treasury) {
        require(_usdcToken != address(0), "Invalid USDC token address");
        require(_treasury != address(0), "Invalid treasury address");

        usdcToken = IERC20(_usdcToken);
        treasury = _treasury;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    /**
     * @notice Create a subscription plan
     */
    function createPlan(
        string calldata name,
        string calldata description,
        uint256 monthlyPrice,
        uint256 annualPrice,
        uint256 maxDevices,
        uint256[] calldata contentIds
    ) external whenNotPaused returns (uint256 planId) {
        require(bytes(name).length > 0, "Plan name required");
        require(monthlyPrice > 0, "Monthly price must be greater than 0");
        require(annualPrice > 0, "Annual price must be greater than 0");
        require(maxDevices > 0, "Max devices must be greater than 0");
        require(annualPrice < monthlyPrice * 12, "Annual price should be discounted");

        planId = nextPlanId++;

        plans[planId] = SubscriptionPlan({
            planId: planId,
            creator: msg.sender,
            name: name,
            description: description,
            monthlyPriceUSDC: monthlyPrice,
            annualPriceUSDC: annualPrice,
            maxDevices: maxDevices,
            includedContentIds: contentIds,
            isActive: true,
            subscriberCount: 0,
            createdAt: block.timestamp
        });

        // Track content inclusion
        for (uint256 i = 0; i < contentIds.length; i++) {
            planContentIncluded[planId][contentIds[i]] = true;
        }

        creatorPlans[msg.sender].push(planId);

        emit PlanCreated(planId, msg.sender, name, monthlyPrice, annualPrice);
    }

    /**
     * @notice Subscribe to a plan
     */
    function subscribe(
        uint256 planId,
        bool isAnnual,
        bytes32 initialDeviceFingerprint
    ) external nonReentrant whenNotPaused returns (uint256 subscriptionId) {
        require(plans[planId].isActive, "Plan not active");
        require(initialDeviceFingerprint != bytes32(0), "Device fingerprint required");

        SubscriptionPlan storage plan = plans[planId];
        uint256 price = isAnnual ? plan.annualPriceUSDC : plan.monthlyPriceUSDC;
        uint256 duration = isAnnual ? YEAR_DURATION : MONTH_DURATION;

        subscriptionId = nextSubscriptionId++;

        uint256 periodStart = block.timestamp;
        uint256 periodEnd = periodStart + duration;

        subscriptions[subscriptionId] = Subscription({
            subscriptionId: subscriptionId,
            subscriber: msg.sender,
            planId: planId,
            startedAt: periodStart,
            currentPeriodStart: periodStart,
            currentPeriodEnd: periodEnd,
            nextBillingDate: periodEnd,
            isAnnual: isAnnual,
            autoRenew: true,
            isCancelled: false,
            registeredDevices: new bytes32[](1),
            totalPaid: price
        });

        subscriptions[subscriptionId].registeredDevices[0] = initialDeviceFingerprint;

        // Grant device access
        bytes32 accessKey = keccak256(abi.encodePacked(subscriptionId, initialDeviceFingerprint));
        subscriptionAccess[accessKey] = SubscriptionAccess({
            subscriptionId: subscriptionId,
            deviceFingerprint: initialDeviceFingerprint,
            grantedAt: block.timestamp,
            accessCount: 0,
            isActive: true
        });

        userSubscriptions[msg.sender].push(subscriptionId);
        plan.subscriberCount++;

        // Process payment
        require(
            usdcToken.transferFrom(msg.sender, address(this), price),
            "USDC transfer failed"
        );

        // Calculate fees
        uint256 platformFee = (price * platformFeeBps) / 10000;
        uint256 creatorAmount = price - platformFee;

        creatorBalances[plan.creator] += creatorAmount;
        require(usdcToken.transfer(treasury, platformFee), "Treasury transfer failed");

        emit Subscribed(subscriptionId, msg.sender, planId, isAnnual, price);
        emit DeviceRegistered(subscriptionId, initialDeviceFingerprint);
    }

    /**
     * @notice Renew subscription (auto or manual)
     */
    function renewSubscription(uint256 subscriptionId) external nonReentrant whenNotPaused {
        Subscription storage sub = subscriptions[subscriptionId];
        require(sub.subscriber == msg.sender || sub.autoRenew, "Unauthorized renewal");
        require(!sub.isCancelled, "Subscription cancelled");
        require(
            block.timestamp >= sub.nextBillingDate - GRACE_PERIOD,
            "Too early to renew"
        );

        SubscriptionPlan storage plan = plans[sub.planId];
        require(plan.isActive, "Plan no longer active");

        uint256 price = sub.isAnnual ? plan.annualPriceUSDC : plan.monthlyPriceUSDC;
        uint256 duration = sub.isAnnual ? YEAR_DURATION : MONTH_DURATION;

        // Process payment
        require(
            usdcToken.transferFrom(sub.subscriber, address(this), price),
            "USDC transfer failed"
        );

        // Update subscription period
        sub.currentPeriodStart = sub.currentPeriodEnd;
        sub.currentPeriodEnd = sub.currentPeriodStart + duration;
        sub.nextBillingDate = sub.currentPeriodEnd;
        sub.totalPaid += price;

        // Calculate fees
        uint256 platformFee = (price * platformFeeBps) / 10000;
        uint256 creatorAmount = price - platformFee;

        creatorBalances[plan.creator] += creatorAmount;
        require(usdcToken.transfer(treasury, platformFee), "Treasury transfer failed");

        emit SubscriptionRenewed(subscriptionId, price, sub.currentPeriodEnd);
    }

    /**
     * @notice Cancel subscription
     */
    function cancelSubscription(uint256 subscriptionId) external {
        Subscription storage sub = subscriptions[subscriptionId];
        require(sub.subscriber == msg.sender, "Not subscription owner");
        require(!sub.isCancelled, "Already cancelled");

        sub.isCancelled = true;
        sub.autoRenew = false;

        // Deactivate all device access for this subscription
        for (uint256 i = 0; i < sub.registeredDevices.length; i++) {
            bytes32 accessKey = keccak256(abi.encodePacked(subscriptionId, sub.registeredDevices[i]));
            subscriptionAccess[accessKey].isActive = false;
        }

        plans[sub.planId].subscriberCount--;

        emit SubscriptionCancelled(subscriptionId, msg.sender);
    }

    /**
     * @notice Register additional device for subscription
     */
    function registerDevice(
        uint256 subscriptionId,
        bytes32 deviceFingerprint
    ) external whenNotPaused {
        Subscription storage sub = subscriptions[subscriptionId];
        require(sub.subscriber == msg.sender, "Not subscription owner");
        require(!sub.isCancelled, "Subscription cancelled");
        require(block.timestamp <= sub.currentPeriodEnd, "Subscription expired");

        SubscriptionPlan storage plan = plans[sub.planId];
        require(sub.registeredDevices.length < plan.maxDevices, "Device limit reached");

        // Check if device already registered
        for (uint256 i = 0; i < sub.registeredDevices.length; i++) {
            require(sub.registeredDevices[i] != deviceFingerprint, "Device already registered");
        }

        sub.registeredDevices.push(deviceFingerprint);

        // Grant device access
        bytes32 accessKey = keccak256(abi.encodePacked(subscriptionId, deviceFingerprint));
        subscriptionAccess[accessKey] = SubscriptionAccess({
            subscriptionId: subscriptionId,
            deviceFingerprint: deviceFingerprint,
            grantedAt: block.timestamp,
            accessCount: 0,
            isActive: true
        });

        emit DeviceRegistered(subscriptionId, deviceFingerprint);
    }

    /**
     * @notice Check if subscription grants access to specific content
     */
    function checkSubscriptionAccess(
        address subscriber,
        uint256 contentId,
        bytes32 deviceFingerprint
    ) external view returns (bool hasAccess, uint256 subscriptionId) {
        uint256[] memory userSubs = userSubscriptions[subscriber];

        for (uint256 i = 0; i < userSubs.length; i++) {
            uint256 subId = userSubs[i];
            Subscription storage sub = subscriptions[subId];

            if (sub.isCancelled || block.timestamp > sub.currentPeriodEnd) {
                continue;
            }

            // Check if content is included in plan
            if (!planContentIncluded[sub.planId][contentId]) {
                continue;
            }

            // Check device access
            bytes32 accessKey = keccak256(abi.encodePacked(subId, deviceFingerprint));
            SubscriptionAccess storage access = subscriptionAccess[accessKey];

            if (access.isActive) {
                return (true, subId);
            }
        }

        return (false, 0);
    }

    /**
     * @notice Record content access for analytics
     */
    function recordSubscriptionAccess(
        uint256 subscriptionId,
        bytes32 deviceFingerprint
    ) external {
        bytes32 accessKey = keccak256(abi.encodePacked(subscriptionId, deviceFingerprint));
        require(subscriptionAccess[accessKey].isActive, "No active access");

        subscriptionAccess[accessKey].accessCount++;
    }

    /**
     * @notice Creator withdraws earned balance
     */
    function withdrawCreatorBalance() external nonReentrant {
        uint256 balance = creatorBalances[msg.sender];
        require(balance > 0, "No balance to withdraw");

        creatorBalances[msg.sender] = 0;

        require(usdcToken.transfer(msg.sender, balance), "Withdrawal failed");

        emit CreatorWithdrawal(msg.sender, balance);
    }

    /**
     * @notice Update plan status (creator only)
     */
    function updatePlanStatus(uint256 planId, bool isActive) external {
        require(plans[planId].creator == msg.sender, "Not plan creator");
        plans[planId].isActive = isActive;
    }

    /**
     * @notice Add content to existing plan (creator only)
     */
    function addContentToPlan(uint256 planId, uint256 contentId) external {
        require(plans[planId].creator == msg.sender, "Not plan creator");
        require(!planContentIncluded[planId][contentId], "Content already included");

        plans[planId].includedContentIds.push(contentId);
        planContentIncluded[planId][contentId] = true;
    }

    /**
     * @notice Remove content from plan (creator only)
     */
    function removeContentFromPlan(uint256 planId, uint256 contentId) external {
        require(plans[planId].creator == msg.sender, "Not plan creator");
        require(planContentIncluded[planId][contentId], "Content not included");

        planContentIncluded[planId][contentId] = false;

        // Remove from array (simplified - in production use more efficient method)
        uint256[] storage contentIds = plans[planId].includedContentIds;
        for (uint256 i = 0; i < contentIds.length; i++) {
            if (contentIds[i] == contentId) {
                contentIds[i] = contentIds[contentIds.length - 1];
                contentIds.pop();
                break;
            }
        }
    }

    // Admin functions

    /**
     * @notice Set platform fee (admin only)
     */
    function setPlatformFee(uint256 feeBps) external onlyRole(ADMIN_ROLE) {
        require(feeBps <= 750, "Fee too high"); // Max 7.5%
        platformFeeBps = feeBps;
    }

    /**
     * @notice Emergency pause (admin only)
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @notice Unpause (admin only)
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    // View functions

    /**
     * @notice Get plan details
     */
    function getPlan(uint256 planId) external view returns (SubscriptionPlan memory) {
        return plans[planId];
    }

    /**
     * @notice Get subscription details
     */
    function getSubscription(uint256 subscriptionId) external view returns (Subscription memory) {
        return subscriptions[subscriptionId];
    }

    /**
     * @notice Get user's subscriptions
     */
    function getUserSubscriptions(address user) external view returns (uint256[] memory) {
        return userSubscriptions[user];
    }

    /**
     * @notice Get creator's plans
     */
    function getCreatorPlans(address creator) external view returns (uint256[] memory) {
        return creatorPlans[creator];
    }

    /**
     * @notice Check if subscription is active
     */
    function isSubscriptionActive(uint256 subscriptionId) external view returns (bool) {
        Subscription storage sub = subscriptions[subscriptionId];
        return !sub.isCancelled && block.timestamp <= sub.currentPeriodEnd;
    }
}

